(function(){"use strict";window.D_STUDY_TU101_LECTURES=window.D_STUDY_TU101_LECTURES||{};window.D_STUDY_TU101_LECTURES["l5"]={"id":"l5","lectureNumber":5,"lectureLabel":"Lecture 5","title":"Politics and Democratization in Southeast Asia","theme":"Theme 2 — Southeast Asia in a Changing World","bankVersion":"tu101-l5-v13.16","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support) + user handwritten L5 political-economy summary (uploaded notebook supplement)","summary":[{"id":"tu5s1","titleEn":"1. ASEAN Politics — Different Systems, Shared Constraints","titleTh":"1. การเมือง ASEAN — ระบบต่างกัน แต่มีข้อจำกัดร่วม","memoryEn":"MEMORY HOOK: Different regimes; recurring authoritarian durability.","memoryTh":"จำ: ระบอบต่างกัน แต่ authoritarian durability พบซ้ำ","bullets":[{"en":"Southeast Asia contains democracies, one-party socialist systems, monarchies, military/hybrid regimes and durable dominant-party arrangements.","th":"เอเชียตะวันออกเฉียงใต้มีทั้งประชาธิปไตย รัฐพรรคเดียว ราชาธิปไตย ระบอบทหาร/ผสม และ dominant-party ที่ทนทาน"},{"en":"The lecture’s key question is not simply “democracy or dictatorship?” but why <b>authoritarian durability</b> remains strong despite elections and political change.","th":"คำถามสำคัญไม่ใช่แค่ประชาธิปไตยหรือเผด็จการ แต่คือทำไม <b>authoritarian durability</b> ยังแข็งแม้มีการเลือกตั้ง/เปลี่ยนแปลง"},{"en":"ASEAN was born in 1967 amid anti-colonial nationalism, independence, nation-building and Cold War/communist conflict.","th":"ASEAN เกิดปี 1967 ในบริบท anti-colonialism อิสรภาพ nation-building และสงครามเย็น/คอมมิวนิสต์"},{"en":"Democratization is uneven: formal elections may coexist with elite power, patronage, military influence or restricted civil liberties.","th":"democratization ไม่เท่ากัน การเลือกตั้งอาจอยู่ร่วมกับอำนาจชนชั้นนำ patronage ทหาร หรือข้อจำกัดเสรีภาพ"}],"understandEn":"The region should be compared along dimensions rather than placed in one simple category. Elections, civil liberties, elite competition, military power and institutions can move in different directions.","understandTh":"ควรเปรียบเทียบหลายมิติ ไม่ใช่ติดป้ายเดียว เพราะการเลือกตั้ง เสรีภาพ การแข่งขันชนชั้นนำ อำนาจทหาร และสถาบันอาจพัฒนาไม่พร้อมกัน","diagram":["Elections","Elite power","Military","Civil society"]},{"id":"tu5s2","titleEn":"2. ASEAN Political-Security Community — Sovereignty First","titleTh":"2. ASEAN Political-Security Community — อธิปไตยมาก่อน","memoryEn":"MEMORY HOOK: Peace + consensus + non-interference — but state-centric.","memoryTh":"จำ: สันติภาพ + ฉันทามติ + ไม่แทรกแซง แต่ state-centric","bullets":[{"en":"The APSC framework emphasizes peace, political-security cooperation, <b>non-interference, consensus, sovereignty and resilience</b>.","th":"APSC เน้นสันติภาพ ความร่วมมือการเมือง-ความมั่นคง <b>non-interference, consensus, sovereignty, resilience</b>"},{"en":"It covers norm-building, conflict prevention, post-conflict peacebuilding and issues such as terrorism.","th":"ครอบคลุมการสร้างบรรทัดฐาน การป้องกันความขัดแย้ง peacebuilding และประเด็นอย่าง terrorism"},{"en":"The slide criticizes a strongly <b>state-centric</b> perspective with weak civil-society participation and limited internal-conflict/human-rights mechanisms.","th":"สไลด์วิจารณ์มุม <b>state-centric</b> ที่เปิดพื้นที่ civil society น้อย และมีกลไกสิทธิ/ความขัดแย้งภายในจำกัด"},{"en":"Cultural/religious diversity, migrants, women, children and public participation require stronger recognition than classic interstate security frameworks provide.","th":"ความหลากหลาย ผู้อพยพ ผู้หญิง เด็ก และ public participation ต้องการการรับรู้มากกว่ากรอบ interstate security แบบเดิม"}],"understandEn":"ASEAN political cooperation is designed to make very different regimes comfortable working together. The same sovereignty-first design that supports cooperation can limit regional pressure over domestic abuses.","understandTh":"ความร่วมมือ ASEAN ถูกออกแบบให้ระบอบต่างกันทำงานร่วมได้ แต่การให้ sovereignty มาก่อนก็จำกัดแรงกดดันต่อปัญหาภายในรัฐ","diagram":["Sovereignty","Consensus","State-centric","Participation gap"]},{"id":"tu5s3","titleEn":"3. Indonesia & the Philippines — Electoral Democracy, Persistent Power Networks","titleTh":"3. Indonesia และ Philippines — เลือกตั้งได้ แต่เครือข่ายอำนาจยังอยู่","memoryEn":"MEMORY HOOK: Democratic institutions do not automatically erase old networks.","memoryTh":"จำ: สถาบันประชาธิปไตยไม่ได้ลบเครือข่ายอำนาจเดิมอัตโนมัติ","bullets":[{"en":"Indonesia is presented as a presidential representative republic, but the lecture traces Sukarno’s Guided Democracy, Suharto’s authoritarian era and post-authoritarian institutional problems.","th":"Indonesia เป็น presidential republic แต่สไลด์ย้อน Guided Democracy ของ Sukarno, ยุค Suharto และปัญหาสถาบันหลังเผด็จการ"},{"en":"Post-Suharto democratization changed formal institutions, yet corruption, factionalism and residual military networks can persist.","th":"หลัง Suharto สถาบันเปลี่ยน แต่ corruption, factionalism และเครือข่ายทหารบางส่วนยังคงอยู่"},{"en":"The Philippines is a presidential constitutional republic with strong electoral politics and civil society, but also <b>local godfathers, patronage, vote buying and political families</b>.","th":"Philippines มีการเลือกตั้ง/civil society แข็ง แต่ยังมี <b>local godfathers, patronage, vote buying และ political families</b>"},{"en":"People Power and election-monitoring groups such as NAMFREL show how civil society can challenge entrenched power.","th":"People Power และกลุ่มติดตามเลือกตั้งอย่าง NAMFREL แสดงพลัง civil society ต่ออำนาจฝังราก"}],"understandEn":"Both cases show why democratization is a process rather than a switch. Formal electoral institutions can expand while older patronage, military or dynastic networks adapt to the new rules.","understandTh":"สองกรณีแสดงว่า democratization เป็นกระบวนการ ไม่ใช่สวิตช์ สถาบันเลือกตั้งขยายได้พร้อมกับเครือข่ายเก่าที่ปรับตัว","diagram":["Elections","Patronage","Civil society","Old networks adapt"]},{"id":"tu5s4","titleEn":"4. Malaysia, Singapore & Brunei — Different Routes to Political Stability","titleTh":"4. Malaysia, Singapore และ Brunei — เส้นทางความมั่นคงการเมืองต่างกัน","memoryEn":"MEMORY HOOK: Coalition/ethnicity • dominant party • absolute monarchy.","memoryTh":"จำ: coalition/ชาติพันธุ์ • dominant party • absolute monarchy","bullets":[{"en":"Malaysia is a <b>federal constitutional monarchy</b> with a rotating Yang di-Pertuan Agong and politics strongly shaped by ethnicity and coalition competition.","th":"Malaysia เป็น <b>federal constitutional monarchy</b> มีกษัตริย์หมุนเวียน และการเมืองผูกกับชาติพันธุ์/coalition"},{"en":"Singapore is a parliamentary republic where the PAP’s long dominance, state capacity and emphasis on collective stability coexist with limits on political expression.","th":"Singapore เป็น parliamentary republic ที่ PAP ครองยาว รัฐมี capacity สูง และเน้น stability พร้อมข้อจำกัด political expression"},{"en":"Brunei’s <b>Malay Islamic Monarchy</b> concentrates executive and religious authority in the Sultan and differs sharply from electoral republics.","th":"Brunei ใช้ <b>Malay Islamic Monarchy</b> รวมอำนาจบริหาร/ศาสนาไว้ที่ Sultan ต่างจาก electoral republics ชัดเจน"}],"understandEn":"These cases warn against treating prosperity or elections as the only indicator of political regime type. Institutional structure, competition, media/civil society space and executive power all matter.","understandTh":"กรณีเหล่านี้เตือนว่าอย่าดูแค่ความมั่งคั่งหรือมีเลือกตั้ง ต้องดูโครงสร้าง การแข่งขัน พื้นที่สื่อ/civil society และอำนาจฝ่ายบริหารด้วย","diagram":["Malaysia coalition","Singapore PAP","Brunei monarchy","Different regimes"]},{"id":"tu5s5","titleEn":"5. Cambodia, Myanmar, Laos & Vietnam — Authoritarian Variants","titleTh":"5. Cambodia, Myanmar, Laos และ Vietnam — รูปแบบ authoritarian ที่ต่างกัน","memoryEn":"MEMORY HOOK: Dominant party • military • communist one-party.","memoryTh":"จำ: dominant party • military • communist one-party","bullets":[{"en":"Cambodia is formally multiparty but the slide emphasizes long-running CPP dominance and dynastic succession from Hun Sen to Hun Manet.","th":"Cambodia มีรูปแบบ multiparty แต่สไลด์เน้น CPP dominance และการสืบอำนาจจาก Hun Sen ไป Hun Manet"},{"en":"Myanmar combines military power, ethnic conflict and interrupted democratization; the slide highlights the Tatmadaw, NLD period and the 2021 coup.","th":"Myanmar มีอำนาจทหาร ความขัดแย้งชาติพันธุ์ และ democratization ที่ถูกขัดจังหวะ โดยสไลด์เน้น Tatmadaw, NLD และ coup 2021"},{"en":"Laos remains a one-party communist state under the LPRP; Vietnam is likewise a one-party socialist state under the Communist Party.","th":"Laos เป็นรัฐคอมมิวนิสต์พรรคเดียว LPRP; Vietnam เป็นรัฐสังคมนิยมพรรคเดียวภายใต้ Communist Party"},{"en":"These systems differ internally, but all limit open competition for national political power in ways unlike multiparty liberal democracy.","th":"แต่ละระบบต่างรายละเอียด แต่ต่างก็จำกัดการแข่งขันเปิดเพื่ออำนาจระดับชาติเมื่อเทียบกับ liberal multiparty democracy"}],"understandEn":"Authoritarianism is not one identical model. Military rule, one-party socialism and dominant-party electoral systems use different institutions to organize and limit competition.","understandTh":"authoritarianism มีหลายแบบ ทั้ง military rule, one-party socialism และ dominant-party electoral system ใช้สถาบันต่างกันเพื่อจำกัดการแข่งขัน","diagram":["CPP dominance","Tatmadaw","LPRP","CPV"]},{"id":"tu5s6","titleEn":"6. Political Families — Democracy Can Be Dynastic","titleTh":"6. Political Families — ประชาธิปไตยก็มีราชวงศ์การเมืองได้","memoryEn":"MEMORY HOOK: Family name + patronage + networks + succession.","memoryTh":"จำ: ชื่อครอบครัว + patronage + network + succession","bullets":[{"en":"Purdey’s reading shows political families embedded in parties, bureaucracy and economic networks while maintaining strong loyalty to the family dynasty.","th":"บทอ่าน Purdey แสดงครอบครัวการเมืองฝังในพรรค ราชการ เศรษฐกิจ แต่ loyalty หลักยังอยู่ที่ family dynasty"},{"en":"Dynasties often rely on <b>patronage, family narratives, historical prestige and organizational networks</b>.","th":"dynasty ใช้ <b>patronage เรื่องเล่าครอบครัว prestige ทางประวัติศาสตร์ และเครือข่ายองค์กร</b>"},{"en":"Succession is difficult: bloodline alone does not guarantee charisma, skill or popular appeal, so families may sideline heirs or temporarily outsource leadership.","th":"succession ยาก เพราะสายเลือดไม่รับประกัน charisma/skill/popularity จึงอาจข้ามทายาทหรือใช้คนนอกชั่วคราว"},{"en":"Political families can change parties and alliances pragmatically while preserving the family brand and local power base.","th":"ครอบครัวการเมืองอาจเปลี่ยนพรรค/พันธมิตรอย่าง pragmatic แต่รักษา family brand และฐานอำนาจท้องถิ่น"}],"understandEn":"Dynasties survive not because elections disappear, but because family resources can be converted into electoral advantages. Yet voters and rivals can still punish weak or corrupt families.","understandTh":"dynasty อยู่รอดไม่ใช่เพราะไม่มีเลือกตั้ง แต่เพราะทรัพยากรครอบครัวแปลงเป็นข้อได้เปรียบเลือกตั้งได้ อย่างไรก็ตามผู้เลือกตั้ง/คู่แข่งยังลงโทษได้","diagram":["Family brand","Patronage","Succession","Electoral adaptation"]},{"id":"tu5s7","titleEn":"7. Civil Society & Democratization — More Than Elections","titleTh":"7. Civil Society และ Democratization — มากกว่าการเลือกตั้ง","memoryEn":"MEMORY HOOK: Participation can constrain power, but can also be restricted or co-opted.","memoryTh":"จำ: participation จำกัดอำนาจได้ แต่ก็ถูกจำกัดหรือ co-opt ได้","bullets":[{"en":"Civil society includes non-state organizations and movements that monitor government, elections, rights and public policy.","th":"civil society รวมองค์กร/ขบวนการนอกรัฐที่ติดตามรัฐบาล การเลือกตั้ง สิทธิ และนโยบาย"},{"en":"The Philippines examples show election monitoring and mass mobilization; other regimes tightly restrict independent media and political organization.","th":"Philippines แสดง election monitoring/มวลชน ขณะที่บางระบอบจำกัดสื่อและองค์กรการเมืองอิสระมาก"},{"en":"Purdey notes that dynastic families may <b>co-opt civil society</b> through welfare, charity and patronage, making organized opposition harder.","th":"Purdey ชี้ว่า dynasty อาจ <b>co-opt civil society</b> ผ่าน welfare/charity/patronage ทำให้ต่อต้านยาก"},{"en":"Democratization therefore requires attention to participation, accountability, institutions and real competition—not just whether an election occurs.","th":"ดังนั้น democratization ต้องดู participation, accountability, institutions และการแข่งขันจริง ไม่ใช่แค่มีเลือกตั้ง"}],"understandEn":"Civil society can widen political voice, but its impact depends on legal space, resources, organizational independence and whether elites can co-opt or repress it.","understandTh":"civil society เพิ่มเสียงประชาชนได้ แต่ผลขึ้นกับพื้นที่กฎหมาย ทรัพยากร ความอิสระ และความสามารถของ elite ในการ co-opt/กด","diagram":["Civil society","Accountability","Co-optation","Democratic quality"]},{"id":"tu5s8","titleEn":"8. Notebook Supplement — Capitalism, State Capitalism & Hybrid Models","titleTh":"8. Notebook Supplement — Capitalism, State Capitalism และ Hybrid Models","memoryEn":"MEMORY HOOK: power is military + economic/financial; systems differ by who controls the game.","memoryTh":"จำ: power = military + econ/fin; ระบบต่างกันที่ใคร control the game","bullets":[{"en":"The notebook starts from <b>China & India’s growth → a more multipolar world</b> and marks <b>hybrid models</b> (especially China) as important.","th":"โน้ตเริ่มจาก <b>China & India growth → world multipolar</b> และเน้น <b>hybrid models</b> โดยเฉพาะ China"},{"en":"It emphasizes that <b>power</b> is not only military: the U.S. example is written as <b>military power + economic / financial power</b>.","th":"โน้ตเน้นว่า <b>power</b> ไม่ใช่แค่ทหาร: ตัวอย่าง U.S. = <b>military + economic / financial power</b>"},{"en":"Main tension in the reading note: <b>Open Market vs Nation Sovereignty</b>, with “safety” written beside sovereignty.","th":"main tension ในโน้ต: <b>Open Market vs Nation Sovereignty</b> และเขียน “safety” ข้าง sovereignty"},{"en":"The page’s political-economy typology distinguishes <b>Capitalism</b> (private control / free), <b>Communism</b> (state control), <b>Socialism</b> (private + state for equality), and <b>State capitalism</b> (the state picks players / sets the game while firms compete within sectors).","th":"typology ในโน้ตแยก <b>Capitalism</b>, <b>Communism</b>, <b>Socialism</b>, <b>State capitalism</b> ตามระดับการควบคุมของ private/state"},{"en":"Example-country rows in the notebook place the U.S. / Switzerland under capitalism, Finland / Denmark under socialism, and China / Russia / Vietnam under state capitalism; China also appears as a <b>hybrid</b> case.","th":"ตัวอย่างในโน้ตวาง U.S./Switzerland ฝั่ง capitalism, Finland/Denmark ฝั่ง socialism, China/Russia/Vietnam ฝั่ง state capitalism และยังชี้ China เป็น <b>hybrid</b>"},{"en":"Reading 2 is summarized as China’s <b>“Socialist Market Economy”</b>: state ownership / SOEs coexist with competitive private capital — the notebook’s own conclusion is <b>“but China: mix!”</b>","th":"Reading 2 สรุป China เป็น <b>“Socialist Market Economy”</b>: SOEs/state ownership อยู่ร่วมกับ competitive private capital — โน้ตสรุปว่า <b>“but China: mix!”</b>"}],"understandEn":"The notebook is not presenting four perfectly sealed boxes. Its own China example shows why hybrid models matter: a state can use markets and private capital while still selecting strategic players and preserving large state-owned enterprises.","understandTh":"โน้ตไม่ได้บอกว่า 4 ระบบแยกขาดกัน เพราะกรณี China เองชี้ hybrid: ใช้ market/private capital ได้พร้อมกับ state selection และ SOEs","diagram":["Military + econ/fin power","Open market ↔ sovereignty","Capitalism / socialism","State capitalism","Hybrid China"]},{"id":"tu5s9","titleEn":"9. Notebook Supplement — International System & Systemic Change","titleTh":"9. Notebook Supplement — International System และ Systemic Change","memoryEn":"MEMORY HOOK: system = actors + relationships + rules; change = gradual or critical.","memoryTh":"จำ: system = actors + relationships + rules; change = gradual หรือ critical","bullets":[{"en":"Using the Goldstein & Pevehouse note, the <b>international system</b> is drawn as <b>structure / rules & patterns of interaction</b> connected to <b>actors / relationships among the world’s states</b>.","th":"ตามโน้ต Goldstein & Pevehouse, <b>international system</b> = <b>structure / rules & patterns of interaction</b> + <b>actors / relationships among world’s states</b>"},{"en":"The page labels a <b>big change of order</b> as a change in the recurring pattern of relationships between countries.","th":"โน้ตเรียก <b>big change of order</b> ว่าการเปลี่ยน pattern of relationships ที่เกิดซ้ำระหว่างประเทศ"},{"en":"Four drivers are written beside systemic change: <b>war, revolution, globalization, technology</b>.","th":"drivers 4 อย่างในโน้ต: <b>war, revolution, globalization, technology</b>"},{"en":"<b>Systemic change theory</b> is split into two types: <b>1) incremental accumulation</b> (gradual) and <b>2) critical juncture</b> (sudden).","th":"<b>Systemic change theory</b> แบ่ง 2 แบบ: <b>incremental accumulation</b> = gradual และ <b>critical juncture</b> = sudden"},{"en":"The page links the rise of China and India to a more <b>multipolar</b> distribution of power and uses the Buzan reading as supporting context for changing centers of power.","th":"โน้ตเชื่อมการขึ้นของ China/India กับโลกที่ <b>multipolar</b> มากขึ้น และใช้ Buzan reading เป็นบริบทเรื่องศูนย์อำนาจที่เปลี่ยนไป"}],"understandEn":"Think of the international system as a repeated pattern, not a list of countries. If actors, rules and relationships accumulate changes slowly, the order shifts incrementally; if a war, revolution or other major break reorganizes the pattern quickly, the notebook labels that a critical juncture.","understandTh":"ให้คิด international system เป็น pattern ที่เกิดซ้ำ ไม่ใช่รายชื่อประเทศ ถ้ากติกา/actors/relationships เปลี่ยนสะสมช้า ๆ = incremental; ถ้ามีจุดหักใหญ่เปลี่ยนเร็ว = critical juncture","diagram":["Actors + rules","Recurring order","Incremental accumulation","Critical juncture","New pattern"]}],"parts":{"tu5-foundations":{"label":"Part 1 • Regime Diversity, ASEAN & Democratization","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support)","summaries":["tu5s1","tu5s2","tu5s8","tu5s9"],"topics":["Politics and democratization in Southeast Asia","Institutions, elites, geopolitics, and non-traditional security"]},"tu5-id-ph":{"label":"Part 2 • Indonesia & Philippines","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support)","summaries":["tu5s3"],"topics":["Politics and democratization in Southeast Asia","Institutions, elites, geopolitics, and non-traditional security"]},"tu5-regimes":{"label":"Part 3 • Malaysia, Singapore, Brunei, Cambodia, Myanmar, Laos & Vietnam","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support)","summaries":["tu5s4","tu5s5"],"topics":["Politics and democratization in Southeast Asia","Institutions, elites, geopolitics, and non-traditional security"]},"tu5-dynasty":{"label":"Part 4 • Political Families, Civil Society & Democratic Quality","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support)","summaries":["tu5s6","tu5s7"],"topics":["Political families and dynasties","Politics and democratization in Southeast Asia"]},"tu5-all":{"label":"Cumulative • Lecture 5","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support)","summaries":["tu5s1","tu5s2","tu5s3","tu5s4","tu5s5","tu5s6","tu5s7"],"topics":null,"cumulative":true},"tu5-notebook-update":{"label":"Part 5 • Notebook Supplement — Political Economy & Systemic Change","source":"Professor Morragotwong politics/democratization slide (primary) + Purdey political-families reading (support) + user handwritten L5 political-economy summary (uploaded notebook supplement)","summaries":["tu5s8","tu5s9"],"topics":["Institutions, elites, geopolitics, and non-traditional security"],"recordSafeSupplement":true}},"review":{"tu5-foundations":[{"q":"What best characterizes political systems across Southeast Asia in the lecture?","opts":["They are highly diverse, ranging from electoral democracies to one-party, military and monarchical systems","All ASEAN states use the same parliamentary democracy","Every state is a military junta","Political systems are irrelevant to ASEAN"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide opens by asking how different systems can coexist within ASEAN."},{"q":"What is authoritarian durability?","opts":["The persistence or adaptation of authoritarian power despite pressures for democratization","A short democratic transition","The automatic collapse of all dictatorships","Only military spending"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The lecture emphasizes resistance to democratizing pressures."},{"q":"What historical context shaped ASEAN’s birth in 1967?","opts":["Anti-colonial nationalism, independence, nation-building and Cold War conflict","Post-9/11 counterterrorism only","The digital era alone","European monetary integration"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"These are the background forces listed in the slide."},{"q":"Why does the politics lecture revisit Anderson’s imagined communities?","opts":["Nationalism and nation-building shape the political communities within which ASEAN regimes operate","To argue nations have no political effect","Only to teach printing technology","To replace all regime analysis"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The lecture links nationalism, Cold War state-building and contemporary politics."},{"q":"What is the main orientation of the ASEAN Political-Security Community?","opts":["Peaceful interstate cooperation grounded in sovereignty, consensus and non-interference","Supranational majority rule","Automatic military intervention in members","Abolition of national security"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The blueprint prioritizes state-to-state political-security cooperation."},{"q":"Which issue belongs to the APSC blueprint described in class?","opts":["Conflict prevention, counterterrorism and norm-building","A common ASEAN income tax","One regional political party","Compulsory religious conversion"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Political-security cooperation includes conflict and security norms."},{"q":"What does the slide criticize as state-centric in ASEAN political-security cooperation?","opts":["The framework privileges government/state security over direct civil-society participation and some human-security concerns","It gives NGOs too much formal power","It abolishes sovereignty","It focuses only on local elections"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The slide lists gaps in participation, human rights and internal conflict."},{"q":"What is a trade-off of non-interference?","opts":["It supports sovereign cooperation but limits collective response to domestic abuses or conflicts","It requires intervention in every domestic issue","It creates a federal ASEAN","It removes consensus"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The lecture highlights internal-conflict and rights gaps."},{"q":"What participation gap does the slide identify?","opts":["Civil society has limited formal representation in the security-centered regional framework","Civil society controls the ASEAN Secretariat","NGOs appoint national presidents","Only civil society can make policy"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The lecture explicitly criticizes weak political participation/representation."},{"q":"What is the best way to understand democratization?","opts":["A process involving institutions, competition, rights and participation, not a one-time switch","The first election instantly completes democracy","Only economic growth matters","It means abolishing the state"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The lecture compares uneven transitions and persistent authoritarian features."}],"tu5-id-ph":[{"q":"How is Indonesia described institutionally in the lecture?","opts":["A presidential representative democratic republic with a multiparty system","An absolute monarchy","A one-party communist state","A military colony"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide identifies a presidential republic with president as head of state/government."},{"q":"What political concept is associated with Sukarno in the slide?","opts":["Guided Democracy","Malay Islamic Monarchy","People Power II","ASEAN Way"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Sukarno is linked to independence and Guided Democracy."},{"q":"What does Suharto represent in the lecture’s Indonesia timeline?","opts":["Long authoritarian New Order rule before the democratic transition","The first post-2024 president","A Philippine local boss","A Malaysian monarch"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Suharto is a central example of durable authoritarian rule."},{"q":"What post-transition concern does the slide mention about Indonesia’s military?","opts":["It gave up formal seat allotments but retained influence through territorial networks","It ceased to exist","It became ASEAN’s army","It directly elected the president"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The lecture notes residual military shadow bureaucracy."},{"q":"How is the Philippines described institutionally?","opts":["A constitutional presidential republic with a directly elected president","A communist one-party state","A rotating federal monarchy","An absolute sultanate"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide emphasizes presidential government and a six-year single term."},{"q":"What are political 'godfathers' in the Philippine discussion?","opts":["Local power brokers who use patronage, influence and electoral networks to control resources and office","Religious priests only","Military officers appointed by ASEAN","Neutral election observers"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide links local influence politics to unequal resource allocation and vote buying."},{"q":"What is NAMFREL used to illustrate?","opts":["Civil-society monitoring of elections in the Philippines","A communist party in Laos","A Malaysian royal council","A Chinese security initiative"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide names it as a non-government election-monitoring movement."},{"q":"What did People Power demonstrate in the Philippines?","opts":["Mass civil-society mobilization could remove an entrenched authoritarian president","The military permanently abolished elections","A monarchy was restored","ASEAN directly appointed a president"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide uses People Power against Marcos as a civil-society landmark."},{"q":"What civil-military norm does the Philippine slide emphasize?","opts":["Constitutional supremacy of civilian authority over the military","Military supremacy over elected government","No armed forces","ASEAN command over the army"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The slide describes civilian supremacy as an accepted political norm."},{"q":"What tension does the Duterte case illustrate in the lecture?","opts":["Electoral legitimacy can coexist with authoritarian practices and severe rights concerns","Elections eliminate executive coercion","Presidents cannot use populist security campaigns","Democracy is defined only by economic growth"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide describes democracy with authoritarian features and the drug-war controversy."}],"tu5-regimes":[{"q":"What is Malaysia’s basic constitutional form?","opts":["A federal constitutional monarchy","A unitary communist republic","An absolute military state","A city-state parliamentary republic"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Malaysia is the region’s only federation in the slide."},{"q":"How is Malaysia’s Yang di-Pertuan Agong selected?","opts":["Rotated/elected for a term from among hereditary Malay rulers","Direct universal election from all citizens","Inherited permanently by one dynasty","Appointed by ASEAN"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The monarchy rotates among nine hereditary rulers."},{"q":"What strongly shapes Malaysian party politics in the lecture?","opts":["Ethnic and Malay/Bumiputera political cleavages","Complete absence of identity politics","Only military rank","No party coalitions"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide notes many parties historically organized around ethnic constituencies."},{"q":"What is Singapore’s formal political system?","opts":["A parliamentary republic","An absolute monarchy","A communist federation","A military junta"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide describes a city-state parliamentary republic."},{"q":"What role does the PAP play in Singapore’s political story?","opts":["It has been the dominant governing party for a long period","It is a banned opposition movement","It is the royal family","It is ASEAN’s security council"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"PAP dominance is central to the lecture’s semi-democratic discussion."},{"q":"What ideological-political formula defines Brunei in the slide?","opts":["Malay Islamic Monarchy","Guided Democracy","Pancasila","ASEAN federalism"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"MIB combines Malay identity, Islam and monarchy."},{"q":"What tension does the Cambodia case illustrate?","opts":["Formal multiparty institutions coexist with long-term CPP dominance","No political party exists","A fully rotating monarchy controls elections","Military rule ended all parties"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide describes nominal multiparty democracy alongside one-party-like dominance."},{"q":"What institution remains central to Myanmar’s politics in the lecture?","opts":["The Tatmadaw (military)","ASEAN Parliament","PAP","UMNO"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Military influence, ethnic conflict and the 2021 coup are central."},{"q":"What is Laos’s national party structure in the lecture?","opts":["One-party rule under the Lao People’s Revolutionary Party","Competitive two-party presidentialism","Rotating monarchy","Military-free direct democracy"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The LPRP is described as the only legal political party."},{"q":"What institution is described as the most powerful political organization in Vietnam?","opts":["The Communist Party of Vietnam","The ASEAN Secretariat","A hereditary monarchy","Independent provincial parties"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The slide places CPV at the center of state, political and social institutions."}],"tu5-dynasty":[{"q":"What defines a political family in the Purdey reading?","opts":["Multiple family members use shared name, networks and resources to sustain political power across generations","Any household with one voter","Only hereditary monarchies","A political party with no kinship ties"],"ans":0,"topic":"Political families and dynasties","why":"The reading compares dynastic families across Southeast Asian electoral systems."},{"q":"What is patronage in dynastic politics?","opts":["Exchange of resources, favors or access through personalized networks that build political loyalty","A neutral constitutional court","Universal impersonal welfare only","A ban on client relations"],"ans":0,"topic":"Political families and dynasties","why":"Patronage is a recurring power base of families in the reading."},{"q":"Why does a family name matter politically?","opts":["It carries recognition, historical narrative and a brand that can transfer across generations","It legally guarantees office","It replaces all campaigning","It prevents scandals"],"ans":0,"topic":"Political families and dynasties","why":"The reading emphasizes founding figures and family mythology."},{"q":"Why is succession a central vulnerability for political families?","opts":["Bloodline does not guarantee a capable, charismatic or popular heir","Families are legally forbidden to nominate relatives","Every heir is equally popular","Succession has no effect on brands"],"ans":0,"topic":"Political families and dynasties","why":"The reading repeatedly emphasizes regeneration problems."},{"q":"What risk can a strong sense of family entitlement create?","opts":["Younger heirs may prioritize power/wealth over public service and damage the dynasty’s legitimacy","It guarantees better governing skill","It prevents corruption","It eliminates voter judgment"],"ans":0,"topic":"Political families and dynasties","why":"The Djunaid example is used to show entitlement can threaten a family."},{"q":"What does party-switching by political families reveal?","opts":["Family survival and local power can take priority over stable ideological party loyalty","Dynasties never change alliances","Parties fully control all families","Kinship has no strategic role"],"ans":0,"topic":"Political families and dynasties","why":"The reading describes opportunistic alliances such as the Chidchob case."},{"q":"What coercive strategy appears in some political-family cases?","opts":["Violence or intimidation against rivals","Only policy debates","Mandatory coalition sharing","No competition at all"],"ans":0,"topic":"Political families and dynasties","why":"The reading discusses violence in Philippine/Thai local dynastic competition."},{"q":"How can dynasties weaken civil-society opposition?","opts":["By co-opting groups through welfare, charity and patronage relationships","By making civil society legally supreme","By eliminating all social assistance","Only by changing constitutions"],"ans":0,"topic":"Political families and dynasties","why":"Purdey notes cooptation can make anti-dynasty mobilization harder."},{"q":"What democratic vulnerability do political families still face?","opts":["Voters can punish poor performance, corruption or weak successors","Dynasties are legally guaranteed victory","Family names eliminate electoral uncertainty","Civil society cannot affect them"],"ans":0,"topic":"Political families and dynasties","why":"The reading stresses dynasties can fail if public investment disappears."},{"q":"What is the best overall measure of democratization from this lecture?","opts":["Real competition, accountability, rights, participation and institutional constraints together","Election day alone","GDP growth alone","Number of political families alone"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The lecture consistently goes beyond formal regime labels."}],"tu5-notebook-update":[{"q":"What power shift opens the handwritten political-economy page?","opts":["China and India’s growth contributes to a more multipolar world","China and India disappear from world politics","The world becomes permanently unipolar","Only military alliances determine polarity"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The page writes China & India’s growth → world more multipolar."},{"q":"How does the notebook define the importance of power?","opts":["Power includes military plus economic / financial capabilities","Power is only military force","Power is only culture","Power is only population"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The page uses the U.S. as an example: military + econ/fin power."},{"q":"What is the main tension written beside the readings?","opts":["Open Market vs Nation Sovereignty","Democracy vs monarchy only","Urban vs rural identity","Religion vs language"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The note labels “Main tension: Open Mkt vs Nation Sovereignty.”"},{"q":"How does the notebook characterize capitalism?","opts":["Private actors control production in a relatively free market","The state controls all labor and capital","The state chooses every sectoral player","Private ownership is prohibited"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The typology row says capitalism: private controls / free."},{"q":"How does the notebook characterize communism?","opts":["The state controls labor and capital comprehensively","Private actors freely control all production","The state only regulates one strategic sector","Markets determine all ownership"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The handwritten table says state controls all labor/capital."},{"q":"How does the notebook characterize socialism?","opts":["A mix of private and state roles oriented toward greater equality","Only private ownership with no state role","Total state control identical to the communism row","A military alliance system"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The table writes private + state / for equality."},{"q":"What distinguishes state capitalism in the notebook?","opts":["The state selects or shapes key players and sets the competitive game within sectors","The state disappears from the economy","Every firm is necessarily privately independent of government strategy","All trade is banned"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The note says state picks players / sets the game in each sector."},{"q":"Why is China presented as a hybrid model?","opts":["SOEs and state direction coexist with competitive private capital in a “Socialist Market Economy”","China uses no markets at all","China has no state-owned enterprises","China is described as pure laissez-faire capitalism"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The reading note writes Socialist Market Economy, SOEs and private capital, concluding “but China: mix!”"},{"q":"What elements define the international system in the notebook?","opts":["Actors and their relationships plus rules / recurring patterns of interaction","Only geography and climate","Only military technology","Only domestic constitutions"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The page links structure/rules/patterns to actors/relationships among world states."},{"q":"What two types of systemic change are written in the notebook?","opts":["Incremental accumulation and critical juncture","Inflation and deflation","Balancing and bandwagoning","Federalism and unitary rule"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The page labels two types: incremental accumulation and critical juncture."}]},"mastery":{"tu5-foundations":[{"q":"Why is it misleading to rank ASEAN politics only by whether elections exist?","opts":["Elections can coexist with dominant parties, patronage, military influence or restricted civil liberties","Elections automatically guarantee liberal democracy","Countries without elections have identical institutions","Civil liberties are unrelated to democratization"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Regime quality has multiple institutional dimensions."},{"q":"A ruling network allows elections but controls media, patronage and institutions enough to retain power. What concept fits?","opts":["Authoritarian durability through institutional adaptation","Complete democratization","Statelessness","Pure direct democracy"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Authoritarian structures can adapt to electoral forms."},{"q":"Why did sovereignty and non-interference become attractive norms for newly independent Southeast Asian states?","opts":["New states wanted protection for fragile national autonomy after colonialism and conflict","They wanted a supranational ASEAN government","They had no concern about external intervention","They sought to abolish national borders"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Postcolonial state-building made sovereign control highly valued."},{"q":"How can a nation be a 'deep horizontal comradeship' despite inequality?","opts":["People can imagine equal membership in the nation even when social and political power is unequal","All citizens actually have identical resources","Nationalism eliminates class differences","Only elites count as members"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Imagined equality can coexist with real hierarchy."},{"q":"Why is the APSC framework comfortable for very different regime types?","opts":["It protects sovereignty and does not require members to adopt one domestic political model","It forces liberal elections","It gives civil society veto power","It removes national governments"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Sovereignty-first cooperation lowers regime-change fears."},{"q":"Why can norm-building matter even without supranational enforcement?","opts":["Repeated agreement can shape expectations and standards of acceptable state behavior","Norms automatically become criminal law","Norms have no effect without a regional army","Agreement eliminates national interests"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Regional institutions can influence through socialization/reputation."},{"q":"Why can a state-centric security lens overlook internally displaced people?","opts":["It prioritizes interstate stability and government sovereignty rather than vulnerable people inside states","IDPs are always foreign citizens","Internal displacement is purely economic","ASEAN legally forbids data collection"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Human security and state security are not identical."},{"q":"A domestic crisis produces refugees across borders, but members avoid criticizing the government. Which institutional tension is visible?","opts":["Non-interference versus regional human-security consequences","Free trade versus inflation","Monarchy versus federalism only","Language policy versus print capitalism"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Internal crises can create transnational effects that sovereignty rules make hard to address."},{"q":"Why can civil-society participation improve democratic accountability?","opts":["It creates channels for affected groups to monitor, contest and contribute to policy beyond state elites","It guarantees perfect policy","It removes elections","It makes governments unnecessary"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Participation widens the set of voices in decision-making."},{"q":"A country holds competitive elections but journalists are intimidated and the military retains veto power. How should it be assessed?","opts":["Democratization is incomplete because electoral competition coexists with major non-democratic constraints","Fully liberal democratic solely because elections occur","Pure dictatorship with no democratic element at all","Impossible to analyze"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Democracy is multidimensional."}],"tu5-id-ph":[{"q":"Why does formal presidential democracy not by itself describe Indonesia’s full political reality?","opts":["Historical authoritarian legacies, corruption, factionalism and military networks can coexist with democratic institutions","Presidentialism abolishes informal power","Elections remove all patronage","Formal rules never matter"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Formal institutions and informal power must be analyzed together."},{"q":"Why is Guided Democracy relevant to authoritarian durability?","opts":["It shows how nationalist leadership can retain popular legitimacy while concentrating political control","It proves all postcolonial governments are liberal","It removed executive authority","It was a supranational ASEAN institution"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Political legitimacy and liberal pluralism are separate dimensions."},{"q":"Why can post-authoritarian institutions retain traces of the old regime?","opts":["Personnel, patronage and organizational networks can survive formal regime change","Regime change erases all institutions overnight","Old elites are legally unable to participate","Democracy has no institutions"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Transitions transform rules faster than all social networks."},{"q":"What does this illustrate about formal versus informal power?","opts":["Losing an official institutional privilege does not necessarily eliminate organizational influence","Only constitutional text matters","Informal power cannot survive democratization","Territorial networks are purely economic"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Power can persist outside formal seats."},{"q":"Why can a presidential constitutional design coexist with strong local bosses?","opts":["Formal national institutions do not automatically eliminate patronage-based local power structures","Constitutions control every informal network","Local politics disappears under presidentialism","Only monarchies have patronage"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Institutional and clientelist structures can overlap."},{"q":"Why does weak equal state provision strengthen local patronage?","opts":["Citizens may depend on brokers for benefits, turning private networks into political leverage","Equal public services increase dependency on bosses","Patronage requires no resources","Local brokers have no link to elections"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Resource access can create clientelistic dependence."},{"q":"Why can independent election monitoring matter even when elections are formally administered by the state?","opts":["It adds external scrutiny that can deter or expose manipulation and increase public trust","It replaces voting","It makes parties unnecessary","It guarantees preferred candidates win"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Accountability often depends on independent observation."},{"q":"What broader democratization lesson comes from People Power?","opts":["Organized public legitimacy can become a political resource strong enough to challenge formal incumbency","Only constitutional courts can cause change","Civil society never affects regime outcomes","Mass mobilization guarantees later governance quality"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Social mobilization can alter power, although later democratic quality is not guaranteed."},{"q":"Why is civilian supremacy important for democratization?","opts":["It limits the military’s ability to substitute coercive authority for elected civilian decision-making","It makes defense policy unnecessary","It guarantees no corruption","It removes all security threats"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Democratic control requires coercive institutions to remain subordinate to civilian government."},{"q":"Why is 'won an election' insufficient evidence of liberal democracy?","opts":["Liberal democracy also requires rights, constraints on power, due process and accountable institutions","Elections have no democratic relevance","Only unelected leaders can violate rights","Rights matter only in monarchies"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Electoral and liberal dimensions are related but not identical."}],"tu5-regimes":[{"q":"Why is Malaysia useful for separating regime form from political competition?","opts":["It combines constitutional/electoral institutions with long-standing coalition and ethno-political structures","Federalism prevents parties","Monarchy eliminates elections","Ethnicity is legally irrelevant"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Formal structure and patterns of competition both matter."},{"q":"What makes Malaysia’s monarchy unusual in comparative terms?","opts":["The federal kingship rotates among several hereditary state rulers rather than one permanent royal line","It has no monarch","The king is always the prime minister","It is identical to Brunei’s absolute monarchy"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Rotating federal monarchy is a distinctive institutional design."},{"q":"Why can ethno-political organization complicate democratization?","opts":["Competition may mobilize group identity and distribute benefits through communal categories rather than only policy ideology","Ethnicity automatically prevents voting","Group identity always disappears in elections","Federalism bans identity parties"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Identity can structure both representation and patronage."},{"q":"Why can Singapore be described as institutionally electoral yet politically constrained?","opts":["Regular institutions/elections coexist with long PAP dominance and restrictions on opposition, media or political expression","There are no government institutions","All parties have identical power","Political stability automatically equals liberal pluralism"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Electoral form and competitive openness differ."},{"q":"Why is dominant-party rule different from a one-party state?","opts":["Opposition parties formally exist and elections occur, but one party retains overwhelming structural advantage","They are exactly identical by definition","A one-party state has more opposition competition","Dominant parties cannot win elections"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Competition exists in different degrees."},{"q":"Why is Brunei analytically different from Malaysia despite both having Malay monarchies and Islam?","opts":["Brunei concentrates governing authority in an absolute sultanate, while Malaysia has federal constitutional electoral institutions","Malaysia has no monarchy","Brunei is a communist republic","Both have identical executive structures"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Similar cultural elements can sit inside very different political systems."},{"q":"Why is formal multiparty status not enough to assess effective competition?","opts":["One party may control institutions, resources and political space so strongly that alternatives are severely disadvantaged","Party number automatically measures democracy","Dominance has no effect on competition","Only constitutions matter"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Effective contestation depends on power distribution, not just legal party registration."},{"q":"What does the 2021 coup demonstrate about an incomplete democratic transition?","opts":["Formal civilian institutions can remain vulnerable if the military retains autonomous coercive power","Elections permanently remove coup risk","Military organizations become irrelevant after constitutions","Civil society alone controls armed force"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Democratic consolidation requires durable civilian control."},{"q":"Why is one-party socialism different from dominant-party electoralism?","opts":["Legal competition for national governing power is structurally excluded rather than merely unequal","One-party systems have more opposition parties","Dominant parties ban all alternatives by definition","There is no difference in party law"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The degree of legally permitted contestation is different."},{"q":"How can Vietnam combine a market-oriented economy with one-party socialist politics?","opts":["Economic organization and political competition are separate dimensions; market mechanisms do not automatically create multiparty rule","Capitalism always requires liberal democracy","One-party rule forbids any private enterprise by definition","Economic reform eliminates the party"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"Political and economic systems can combine in hybrid ways."}],"tu5-dynasty":[{"q":"Why can political families thrive inside electoral democracy?","opts":["Family reputation, money, patronage and networks can be converted into votes and candidacies","Elections legally require dynasties","Voters cannot reject famous families","Kinship automatically overrides institutions"],"ans":0,"topic":"Political families and dynasties","why":"Democratic competition can be a channel through which inherited political capital is used."},{"q":"Why is patronage resilient where formal institutions are weak or uneven?","opts":["People may rely on personal brokers for services or opportunities that institutions do not reliably provide","Weak institutions eliminate demand for resources","Patronage requires strong universal public services","Voters never respond to material access"],"ans":0,"topic":"Political families and dynasties","why":"Informal networks fill gaps and create reciprocal dependence."},{"q":"Why is a deeper historical family narrative especially valuable to a dynasty?","opts":["It gives successors a ready-made story of legitimacy and public service beyond their individual record","It makes elections unnecessary","It guarantees charisma","It erases opposition"],"ans":0,"topic":"Political families and dynasties","why":"Narrative helps reproduce political identity across generations."},{"q":"Why might a dynasty temporarily 'outsource' leadership to a non-relative?","opts":["To preserve the political machine until a suitable family successor is available","To abolish the family brand","Because voters cannot elect relatives","To end patronage"],"ans":0,"topic":"Political families and dynasties","why":"Dynasties prioritize organizational continuity when a blood heir is weak."},{"q":"Why can inherited political capital become a liability?","opts":["A successor may assume the family name is sufficient and neglect the performance/rapport voters still demand","Voters always prefer entitlement","Family names have no political value","Dynasties never face competition"],"ans":0,"topic":"Political families and dynasties","why":"Inherited brand reduces entry costs but does not guarantee continued consent."},{"q":"Why can a dynasty survive repeated party realignment?","opts":["Its durable assets may be local networks, name recognition and patronage rather than one party label","Voters never notice parties","Electoral law requires switching","Ideology is illegal"],"ans":0,"topic":"Political families and dynasties","why":"The family machine can be more stable than its partisan alliances."},{"q":"Why might violence decline when stronger national parties and ideological competition emerge?","opts":["The cost-benefit of local coercion changes when broader organizations and electoral structures become more important","Violence is impossible in national politics","Dynasties cease to exist","Parties automatically eliminate conflict"],"ans":0,"topic":"Political families and dynasties","why":"Political strategies respond to institutional and competitive context."},{"q":"Why is cooptation different from repression?","opts":["It incorporates or rewards potential opponents rather than simply coercing them","Cooptation always uses military force","Repression means giving benefits","They are identical"],"ans":0,"topic":"Political families and dynasties","why":"Elites can neutralize opposition through incentives as well as threats."},{"q":"What condition makes a dynasty more electorally vulnerable?","opts":["Weak community embedding and reliance on shallow patronage without a durable narrative or performance record","Deep historical legitimacy and strong local networks","Popular public-service reputation","Effective party organization"],"ans":0,"topic":"Political families and dynasties","why":"Families with thinner roots are easier for voters/rivals to displace."},{"q":"A country has elections, active civil society and independent media, but a family repeatedly wins through genuine voter support. Is the family’s presence alone proof the system is non-democratic?","opts":["No; dynastic politics can be a democratic-quality concern, but assessment still depends on freedom, competition and accountability","Yes; any related candidates make democracy impossible","No; political families can never harm democratic quality","Yes; family ties automatically cancel election results"],"ans":0,"topic":"Politics and democratization in Southeast Asia","why":"The lecture asks how power is reproduced, not to infer regime type from one feature alone."}],"tu5-notebook-update":[{"q":"Why can the rise of additional large economies encourage multipolarity?","opts":["More states gain significant economic and strategic weight, distributing influence across several centers","Multipolarity means only one center of power","Economic weight cannot affect international power","More powerful states automatically create one empire"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The note connects growth to a wider distribution of power."},{"q":"A state has a strong military but weak finance and limited economic influence. What would the notebook caution?","opts":["Its overall power cannot be understood from military capability alone","Military power automatically equals total power","Finance never affects influence","Economic systems are unrelated to power"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The notebook explicitly treats power as multidimensional."},{"q":"Why can open markets create a sovereignty tension?","opts":["Cross-border rules and dependence can constrain how freely governments pursue domestic priorities or security goals","Open markets remove all governments","Sovereignty requires zero trade","Markets and state authority can never coexist"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The notebook frames openness and national control as a tension, not an absolute either/or."},{"q":"A system leaves most productive assets and firm decisions to private owners operating through markets. Which notebook category fits?","opts":["Capitalism","Communism","State capitalism","Absolute monarchy"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Private market control is the defining feature in the notebook table."},{"q":"A system places productive resources broadly under state control rather than private ownership. Which category fits the notebook?","opts":["Communism","Capitalism","Friendshoring","Federalism"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Comprehensive state control is the listed distinction."},{"q":"A system combines markets and private ownership with substantial state provision or intervention aimed at equality. Which notebook category fits?","opts":["Socialism","Pure laissez-faire capitalism","Communism as defined in the notebook","Power transition"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The note explicitly uses a mixed private/state formulation."},{"q":"Firms compete, but the government chooses strategic champions and strongly structures sectoral competition. Which category best matches?","opts":["State capitalism","Pure communism with no competition","Laissez-faire capitalism","Anarchism"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"Competition can exist while the state shapes who plays and under what rules."},{"q":"A country maintains large state-owned enterprises while allowing private firms to compete in markets. What does the notebook want you to notice?","opts":["The system can be hybrid rather than fitting one pure category","Mixed institutions are impossible","Private competition proves the state is absent","SOEs automatically eliminate all markets"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"China is the notebook’s explicit mixed-case example."},{"q":"Why is an international system more than a list of countries?","opts":["It includes recurring relationships, rules and interaction patterns among those actors","A system has no patterns","Actors never interact","Rules are purely domestic"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The notebook’s definition explicitly includes structure and relationships."},{"q":"A world order changes slowly through decades of accumulating economic and technological shifts, then another order changes rapidly after a major war. Which pair best describes these cases?","opts":["Incremental accumulation for the first; critical juncture for the second","Critical juncture for both","Incremental accumulation for both","Neither is systemic change"],"ans":0,"topic":"Institutions, elites, geopolitics, and non-traditional security","why":"The notebook contrasts gradual accumulation with sudden breakpoints; war, revolution, globalization and technology are listed as drivers."}]},"cumulativeId":"tu5-all","flashcards":{"id":"tu101-l5","label":"Lecture 5 • Politics and Democratization in Southeast Asia","description":"Political-system diversity, authoritarian durability, civil society, country cases and political dynasties.","cumulativeId":"tu101-l5-full-v1","cumulativeLabel":"Full Lecture • Lecture 5","parts":[{"id":"tu5-l5-foundations-v1","label":"Part 1 • Regime Diversity, ASEAN & Democratization","description":"Political-system diversity, authoritarian durability and the APSC framework.","cards":[{"id":"diversity","front":"What best characterizes political systems across Southeast Asia in the lecture?","back":"They are highly diverse, ranging from electoral democracies to one-party, military and monarchical systems ไทยช่วยจำ: มีเลือกตั้งไม่ได้แปลว่า liberal democracy ครบทุกมิติ"},{"id":"author-durability","front":"What is authoritarian durability?","back":"The persistence or adaptation of authoritarian power despite pressures for democratization ไทยช่วยจำ: อำนาจ authoritarian ปรับตัวให้อยู่ได้แม้มีเลือกตั้ง"},{"id":"asean1967","front":"What historical context shaped ASEAN’s birth in 1967?","back":"Anti-colonial nationalism, independence, nation-building and Cold War conflict ไทยช่วยจำ: รัฐใหม่หลังอาณานิคมหวง sovereignty จึงชอบ non-interference"},{"id":"imagined","front":"Why does the politics lecture revisit Anderson’s imagined communities?","back":"Nationalism and nation-building shape the political communities within which ASEAN regimes operate ไทยช่วยจำ: จินตนาการความเป็นสมาชิกเท่ากันได้แม้ความเหลื่อมล้ำจริงยังอยู่"},{"id":"apsc","front":"What is the main orientation of the ASEAN Political-Security Community?","back":"Peaceful interstate cooperation grounded in sovereignty, consensus and non-interference ไทยช่วยจำ: ร่วมมือได้โดยไม่บังคับให้ระบอบภายในเหมือนกัน"},{"id":"apsc-norms","front":"Which issue belongs to the APSC blueprint described in class?","back":"Conflict prevention, counterterrorism and norm-building ไทยช่วยจำ: norm สร้าง expectation แม้บังคับใช้ไม่แข็ง"},{"id":"statecentric","front":"What does the slide criticize as state-centric in ASEAN political-security cooperation?","back":"The framework privileges government/state security over direct civil-society participation and some human-security concerns ไทยช่วยจำ: national security อย่างเดียวอาจมองข้ามความปลอดภัยของคน"},{"id":"noninterference","front":"What is a trade-off of non-interference?","back":"It supports sovereign cooperation but limits collective response to domestic abuses or conflicts ไทยช่วยจำ: วิกฤตในรัฐอาจกระทบภูมิภาค แต่ non-interference จำกัดการตอบสนอง"},{"id":"civil-gap","front":"What participation gap does the slide identify?","back":"Civil society has limited formal representation in the security-centered regional framework ไทยช่วยจำ: civil society เพิ่มช่องตรวจสอบ/เสนอเสียงนอก elite รัฐ"},{"id":"dem-process","front":"What is the best way to understand democratization?","back":"A process involving institutions, competition, rights and participation, not a one-time switch ไทยช่วยจำ: democratization ต้องดูหลายมิติ ไม่ใช่แค่ ballot"}]},{"id":"tu5-l5-id-ph-v1","label":"Part 2 • Indonesia & Philippines","description":"Democratic transitions, military legacies, patronage, civil society and local power.","cards":[{"id":"indo-system","front":"How is Indonesia described institutionally in the lecture?","back":"A presidential representative democratic republic with a multiparty system ไทยช่วยจำ: formal democracy อยู่ร่วมกับ legacy/network เก่าได้"},{"id":"sukarno","front":"What political concept is associated with Sukarno in the slide?","back":"Guided Democracy ไทยช่วยจำ: ผู้นำมี legitimacy แบบชาตินิยมได้พร้อมกับรวมอำนาจ"},{"id":"suharto","front":"What does Suharto represent in the lecture’s Indonesia timeline?","back":"Long authoritarian New Order rule before the democratic transition ไทยช่วยจำ: เปลี่ยนระบอบไม่ทำให้ network เดิมหายทันที"},{"id":"military-shadow","front":"What post-transition concern does the slide mention about Indonesia’s military?","back":"It gave up formal seat allotments but retained influence through territorial networks ไทยช่วยจำ: เสียเก้าอี้ทางการ ≠ อิทธิพลเครือข่ายหายหมด"},{"id":"ph-system","front":"How is the Philippines described institutionally?","back":"A constitutional presidential republic with a directly elected president ไทยช่วยจำ: กติกาประธานาธิบดีไม่ได้ลบ local patronage"},{"id":"godfathers","front":"What are political 'godfathers' in the Philippine discussion?","back":"Local power brokers who use patronage, influence and electoral networks to control resources and office ไทยช่วยจำ: รัฐแจกจ่ายไม่ทั่ว → คนพึ่ง broker → broker ได้อำนาจการเมือง"},{"id":"namfrel","front":"What is NAMFREL used to illustrate?","back":"Civil-society monitoring of elections in the Philippines ไทยช่วยจำ: observer อิสระช่วยตรวจสอบความน่าเชื่อถือของเลือกตั้ง"},{"id":"people-power","front":"What did People Power demonstrate in the Philippines?","back":"Mass civil-society mobilization could remove an entrenched authoritarian president ไทยช่วยจำ: มวลชนเปลี่ยนอำนาจได้ แต่ไม่ได้รับประกันประชาธิปไตยคุณภาพสูงตลอดไป"},{"id":"civilian-military","front":"What civil-military norm does the Philippine slide emphasize?","back":"Constitutional supremacy of civilian authority over the military ไทยช่วยจำ: กองทัพอยู่ใต้รัฐบาลพลเรือนช่วยป้องกัน veto/coup"},{"id":"duterte","front":"What tension does the Duterte case illustrate in the lecture?","back":"Electoral legitimacy can coexist with authoritarian practices and severe rights concerns ไทยช่วยจำ: ชนะเลือกตั้ง ≠ ได้สิทธิใช้อำนาจโดยไม่มี rule of law/rights"}]},{"id":"tu5-l5-regimes-v1","label":"Part 3 • Malaysia, Singapore, Brunei, Cambodia, Myanmar, Laos & Vietnam","description":"Comparing constitutional, dominant-party, monarchical, military and one-party systems.","cards":[{"id":"malaysia","front":"What is Malaysia’s basic constitutional form?","back":"A federal constitutional monarchy ไทยช่วยจำ: มีสถาบันเลือกตั้ง/รัฐธรรมนูญ แต่ coalition/ชาติพันธุ์กำหนดการแข่งขันมาก"},{"id":"king-malaysia","front":"How is Malaysia’s Yang di-Pertuan Agong selected?","back":"Rotated/elected for a term from among hereditary Malay rulers ไทยช่วยจำ: กษัตริย์สหพันธรัฐหมุนเวียนจากสุลต่านรัฐต่าง ๆ"},{"id":"ethnicity-my","front":"What strongly shapes Malaysian party politics in the lecture?","back":"Ethnic and Malay/Bumiputera political cleavages ไทยช่วยจำ: พรรค/นโยบายอาจผูกกับชุมชนชาติพันธุ์และการกระจายผลประโยชน์"},{"id":"singapore","front":"What is Singapore’s formal political system?","back":"A parliamentary republic ไทยช่วยจำ: มีเลือกตั้ง/รัฐสภา แต่พื้นที่การแข่งขันและ expression ถูกจำกัด"},{"id":"pap","front":"What role does the PAP play in Singapore’s political story?","back":"It has been the dominant governing party for a long period ไทยช่วยจำ: dominant party ≠ one-party state แต่การแข่งขันไม่สมดุล"},{"id":"brunei","front":"What ideological-political formula defines Brunei in the slide?","back":"Malay Islamic Monarchy ไทยช่วยจำ: วัฒนธรรมคล้ายบางส่วน แต่โครงสร้างอำนาจต่างกันมาก"},{"id":"cambodia","front":"What tension does the Cambodia case illustrate?","back":"Formal multiparty institutions coexist with long-term CPP dominance ไทยช่วยจำ: มีหลายพรรคในกฎหมาย แต่การแข่งขันจริงอาจไม่เท่าเทียม"},{"id":"myanmar","front":"What institution remains central to Myanmar’s politics in the lecture?","back":"The Tatmadaw (military) ไทยช่วยจำ: ถ้าทหารยังมีอำนาจอิสระ transition อาจย้อนกลับได้"},{"id":"laos","front":"What is Laos’s national party structure in the lecture?","back":"One-party rule under the Lao People’s Revolutionary Party ไทยช่วยจำ: one-party = ไม่เปิดการแข่งขันพรรคระดับชาติอย่างถูกกฎหมาย"},{"id":"vietnam","front":"What institution is described as the most powerful political organization in Vietnam?","back":"The Communist Party of Vietnam ไทยช่วยจำ: เปิดตลาดเศรษฐกิจได้โดยไม่เปิดการแข่งขันพรรคการเมือง"}]},{"id":"tu5-l5-dynasty-v1","label":"Part 4 • Political Families, Civil Society & Democratic Quality","description":"How dynasties reproduce power and how citizens/civil society can constrain them.","cards":[{"id":"family-def","front":"What defines a political family in the Purdey reading?","back":"Multiple family members use shared name, networks and resources to sustain political power across generations ไทยช่วยจำ: ทรัพยากรครอบครัวแปลงเป็น electoral advantage ได้"},{"id":"patronage","front":"What is patronage in dynastic politics?","back":"Exchange of resources, favors or access through personalized networks that build political loyalty ไทยช่วยจำ: เมื่อสถาบันให้บริการไม่ทั่ว คนพึ่ง network ส่วนบุคคลได้ง่าย"},{"id":"family-name","front":"Why does a family name matter politically?","back":"It carries recognition, historical narrative and a brand that can transfer across generations ไทยช่วยจำ: ชื่อ/เรื่องเล่าครอบครัวส่งต่อ legitimacy ให้รุ่นถัดไป"},{"id":"succession","front":"Why is succession a central vulnerability for political families?","back":"Bloodline does not guarantee a capable, charismatic or popular heir ไทยช่วยจำ: ถ้าทายาทยังไม่พร้อม อาจใช้คนนอกประคอง machine ชั่วคราว"},{"id":"entitlement","front":"What risk can a strong sense of family entitlement create?","back":"Younger heirs may prioritize power/wealth over public service and damage the dynasty’s legitimacy ไทยช่วยจำ: ชื่อดังช่วยเริ่ม แต่ถ้ารุ่นลูกคิดว่าตนสมควรได้อำนาจอัตโนมัติอาจเสีย legitimacy"},{"id":"party-switch","front":"What does party-switching by political families reveal?","back":"Family survival and local power can take priority over stable ideological party loyalty ไทยช่วยจำ: party เปลี่ยนได้ แต่ network/family brand ยังอยู่"},{"id":"coercion","front":"What coercive strategy appears in some political-family cases?","back":"Violence or intimidation against rivals ไทยช่วยจำ: เมื่อโครงสร้างการแข่งขันเปลี่ยน วิธีรักษาอำนาจของ local family ก็เปลี่ยน"},{"id":"coopt-cs","front":"How can dynasties weaken civil-society opposition?","back":"By co-opting groups through welfare, charity and patronage relationships ไทยช่วยจำ: co-opt = ดึง/ให้ผลประโยชน์จนกลายเป็นส่วนของ network"},{"id":"voter-vuln","front":"What democratic vulnerability do political families still face?","back":"Voters can punish poor performance, corruption or weak successors ไทยช่วยจำ: ฐานชุมชนตื้น/brand อ่อนทำให้ dynasty แพ้ได้ง่ายขึ้น"},{"id":"quality","front":"What is the best overall measure of democratization from this lecture?","back":"Real competition, accountability, rights, participation and institutional constraints together ไทยช่วยจำ: dynasty เป็นสัญญาณให้ตรวจ power แต่ต้องดูการแข่งขัน/เสรีภาพจริงร่วมกัน"}]},{"id":"tu5-l5-notebook-v1","label":"Part 5 • Notebook Supplement — Political Economy & Systemic Change","description":"Notebook-derived political-economy and international-system questions staged separately from the original four parts.","cards":[{"id":"nb-multipolar","front":"What shift does China/India growth support?","back":"A more multipolar world. ไทยช่วยจำ: อำนาจกระจายหลายศูนย์มากขึ้น"},{"id":"nb-power","front":"What dimensions of power does the notebook emphasize?","back":"Military + economic/financial power. ไทยช่วยจำ: อย่าดู military อย่างเดียว"},{"id":"nb-open-sovereignty","front":"What main tension does the notebook highlight?","back":"Open Market vs Nation Sovereignty. ไทยช่วยจำ: ตลาดเปิดอาจชนกับ autonomy/safety ของรัฐ"},{"id":"nb-capitalism","front":"How is capitalism defined in the notebook?","back":"Private control with relatively free markets. ไทยช่วยจำ: private sector เป็นตัวหลัก"},{"id":"nb-communism","front":"How is communism defined in the notebook?","back":"State controls labor and capital broadly. ไทยช่วยจำ: รัฐควบคุมปัจจัยการผลิตอย่างกว้าง"},{"id":"nb-socialism","front":"How is socialism summarized in the notebook?","back":"Private + state roles, with equality as a goal. ไทยช่วยจำ: ผสม private/state เพื่อ equality"},{"id":"nb-statecap","front":"What is state capitalism in the notebook?","back":"State shapes key players/rules while competition can still occur. ไทยช่วยจำ: รัฐกำหนด player/game แต่ยังมีการแข่งขันได้"},{"id":"nb-china-hybrid","front":"Why is China a hybrid case?","back":"SOEs/state direction coexist with market competition and private capital. ไทยช่วยจำ: China = mix ไม่เข้ากล่องเดียว"},{"id":"nb-system","front":"What makes an international system?","back":"Actors + relationships + rules/patterns of interaction. ไทยช่วยจำ: ไม่ใช่แค่รายชื่อรัฐ แต่รวม pattern ความสัมพันธ์"},{"id":"nb-systemchange","front":"What are the two systemic-change types?","back":"Incremental accumulation (gradual) and critical juncture (sudden). ไทยช่วยจำ: ค่อย ๆ สะสม vs จุดหักเปลี่ยนเร็ว"}]}]},"recordSafeExpansion":{"version":"v13.19-draft","strategy":"New notebook-update part IDs; original four parts and legacy 40-question cumulative remain unchanged.","originalBankVersionPreserved":"tu101-l5-v13.16"}};window.dispatchEvent(new CustomEvent("d-study-tu101-module-loaded",{detail:{id:"l5"}}));})();